package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Runs after {@link ValidateUniqueTelephone} and before {@link BuildOwner}. A household is a set
 * of owners with the same last name at the same address, compared case-insensitively with
 * collapsed whitespace.
 *
 * <p>When the request does not opt in with {@code sharesHousehold = true} and another owner
 * already shares the household, rejects the create with a 409.
 *
 * <p>When {@code sharesHousehold = true} and another owner already shares the household, the
 * create is allowed and all members of the household are assigned the same stable
 * {@code householdId} (a deterministic function of the normalized last name and address): any
 * existing members missing it are back-filled and saved, and the identifier is published for
 * {@link BuildOwner} to stamp onto the new owner. Always publishes the household identifier
 * variable (empty when the new owner is not joining a shared household).
 */
public class ValidateUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository,
            Out<HouseholdId> householdIdOut) throws DuplicateHouseholdException {
        String lastName = normalize(request.getLastName());
        String address = normalize(request.getAddress());

        List<Owner> household = new ArrayList<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(normalize(existing.getAddress()))) {
                household.add(existing);
            }
        }

        if (household.isEmpty()) {
            // No existing household member: nothing to share, nothing to reject.
            householdIdOut.set(new HouseholdId(""));
            return;
        }

        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            throw new DuplicateHouseholdException("An owner named " + request.getLastName()
                    + " already exists at " + request.getAddress());
        }

        // Sharing a household: give every member the same stable identifier.
        String householdId = householdId(lastName, address);
        for (Owner member : household) {
            if (!householdId.equals(member.getHouseholdId())) {
                member.setHouseholdId(householdId);
                ownerRepository.save(member);
            }
        }
        householdIdOut.set(new HouseholdId(householdId));
    }

    /**
     * Stable identifier for the household: the first 12 upper-case hex characters of the
     * SHA-256 of the normalized last name and address, so every owner in the same household
     * derives the same value regardless of creation order.
     */
    private static String householdId(String lastName, String address) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((lastName + "\n" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /**
     * Normalize a name or address for household comparison: trim, collapse any run of
     * whitespace to a single space, and lower-case. Yields {@code ""} for a {@code null} input.
     */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /**
     * Carrier for the resolved household identifier published to {@link BuildOwner}. A dedicated
     * type keeps the variable unambiguous (matched by type) and distinct from other strings in
     * the pipeline. An empty {@link #value()} means the new owner is not joining a shared
     * household.
     */
    public record HouseholdId(String value) {
    }
}

